type SurveyBookSeed = {
  book: string;
  author: string;
  date: string;
  audience: string;
  theme: string;
  keyVerse: string;
  purpose: string;
  outline: Array<{ title: string; reference: string; summary: string }>;
  keyPeople: string[];
  keyPlaces: string[];
  christInTheBook: string;
  memoryVerses: string[];
  keyThemes?: string[];
};

function surveyResourcesForBook(book: string): ChapterResourceRecommendation[] {
  return [
    {
      id: `${book.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-survey-easton`,
      kind: "Dictionary",
      title: "Easton's Bible Dictionary",
      author: "M. G. Easton",
      status: "available",
      note: `Quick lookup for people, places, and Bible background in ${book}.`,
      resourceSlug: "eastons-bible-dictionary",
    },
    {
      id: `${book.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-survey-nave`,
      kind: "Library Resource",
      title: "Nave's Topical Bible",
      author: "Orville J. Nave",
      status: "available",
      note: `Trace key themes and related passages while studying ${book}.`,
      resourceSlug: "naves-topical-bible",
    },
    {
      id: `${book.toLowerCase().replace(/[^a-z0-9]+/g, "-")}-survey-mh`,
      kind: "Commentary",
      title: MATTHEW_HENRY_COMMENTARY_COLLECTION,
      author: "Matthew Henry",
      status: "planned",
      note: "Use reviewed public chapters where available; fuller coverage remains in review before public display.",
      warning: "Use with discernment",
    },
  ];
}

function createSurveyIntroduction(seed: SurveyBookSeed): BookIntroduction {
  return {
    book: seed.book,
    overview: {
      author: seed.author,
      date: seed.date,
      audience: seed.audience,
      theme: seed.theme,
      keyVerse: seed.keyVerse,
      purpose: seed.purpose,
    },
    outline: seed.outline,
    keyThemes: seed.keyThemes,
    keyPeople: seed.keyPeople,
    keyPlaces: seed.keyPlaces,
    christInTheBook: seed.christInTheBook,
    memoryVerses: seed.memoryVerses,
    recommendedResources: surveyResourcesForBook(seed.book),
    sourceNotes: [
      "Concise survey summary prepared from the KJV book content for beta study workflow coverage.",
      "Future handbook quotations or expanded survey notes should be imported only after source, rights, and doctrinal review.",
    ],
  };
}

