function normalizeSermonSlide(slide: Partial<SermonSlide>, index: number): SermonSlide {
  const type = SERMON_SLIDE_TYPES.includes(slide.type as SermonSlideType) ? slide.type as SermonSlideType : "Main Point";
  const layout = SERMON_SLIDE_LAYOUTS.includes(slide.layout as SermonSlideLayout) ? slide.layout as SermonSlideLayout : "Centered";
  const backgroundStyle = SERMON_SLIDE_BACKGROUND_STYLES.includes(slide.backgroundStyle as SermonSlideBackgroundStyle) ? slide.backgroundStyle as SermonSlideBackgroundStyle : "Theme";
  const imageSlot = typeof slide.imageSlot === "string" && slide.imageSlot in SERMON_SLIDE_IMAGE_SLOTS ? slide.imageSlot as SermonSlideImageSlotId : "open-bible";
  const fontScale = ["Compact", "Normal", "Large"].includes(slide.fontScale ?? "") ? slide.fontScale as SermonSlideFontScale : "Normal";
  const titleScale = ["Small", "Medium", "Large"].includes(slide.titleScale ?? "") ? slide.titleScale as SermonSlideTitleScale : "Medium";
  const textPlacement = ["Center", "Left", "Bottom"].includes(slide.textPlacement ?? "") ? slide.textPlacement as SermonSlideTextPlacement : "Center";
  const accentStyle = ["None", "Line", "Badge", "Panel"].includes(slide.accentStyle ?? "") ? slide.accentStyle as SermonSlideAccentStyle : "Line";
  const verseDisplay = ["Reference + Text", "Text Only", "Reference Only"].includes(slide.verseDisplay ?? "") ? slide.verseDisplay as SermonSlideVerseDisplay : "Reference + Text";
  const backgroundIntensity = ["Soft", "Balanced", "Strong"].includes(slide.backgroundIntensity ?? "") ? slide.backgroundIntensity as SermonSlideBackgroundIntensity : "Balanced";
  return {
    id: slide.id || makeId("slide"),
    type,
    title: slide.title ?? `${type} ${index + 1}`,
    subtitle: slide.subtitle ?? "",
    body: slide.body ?? "",
    bibleText: slide.bibleText ?? "",
	    speakerNotes: slide.speakerNotes ?? "",
	    backgroundStyle,
	    imageTheme: slide.imageTheme ?? SERMON_SLIDE_IMAGE_SLOTS[imageSlot].label,
	    imageSlot,
	    layout,
	    fontScale,
	    titleScale,
	    textPlacement,
	    accentStyle,
	    verseDisplay,
	    backgroundIntensity,
	    showImageMotif: slide.showImageMotif ?? true,
	    showTypeLabel: slide.showTypeLabel ?? false,
	    showImageLabel: slide.showImageLabel ?? false,
	    showFooterBranding: slide.showFooterBranding ?? false,
	  };
}

function sermonSlideThemeId(value: unknown): SermonSlideThemeId {
  return typeof value === "string" && value in SERMON_SLIDE_THEMES ? value as SermonSlideThemeId : "classic-pulpit";
}

function normalizeSermonEntry(entry: Partial<SermonEntry>): SermonEntry | null {
  if (!entry.id) return null;
  const now = new Date().toISOString();
  const status = ["Draft", "Ready", "Preached", "Taught", "Archived"].includes(entry.status ?? "Draft") ? entry.status ?? "Draft" : "Draft";
  const sectionOrder = Array.isArray(entry.sectionOrder)
    ? [
        ...entry.sectionOrder.filter((section): section is SermonSectionKey => SERMON_SECTION_FIELDS.includes(section as SermonSectionKey)),
        ...SERMON_SECTION_FIELDS.filter((section) => !entry.sectionOrder?.includes(section)),
      ]
    : SERMON_SECTION_FIELDS;
  return {
    ...EMPTY_SERMON_ENTRY,
	    ...entry,
	    kind: entry.kind === "Lesson" ? "Lesson" : "Sermon",
	    status,
	    sectionOrder,
	    targetMinutes: Number(entry.targetMinutes) > 0 ? Number(entry.targetMinutes) : 30,
	    slides: Array.isArray(entry.slides) ? entry.slides.map(normalizeSermonSlide) : [],
	    slideTheme: sermonSlideThemeId(entry.slideTheme),
	    createdAt: entry.createdAt ?? now,
	    updatedAt: entry.updatedAt ?? now,
	    archived: Boolean(entry.archived || status === "Archived"),
	  };
}

